-- lead still shows its event through source_event_id, and a Meta lead its ad through source_ad_id.
-- Run only after My Fifty and Edge stopped reading the column (my-fifty and renellence-edge no-hubspot, 2026-10-21).
-- Listed in CHANGELOG-v2.md. Safe to run again.
begin;
select set_config('app.source', 'import', true);
alter table public.contacts drop column if exists source_detail;
commit;

-- ==== db/v2-005-edge-redesign.sql
-- Supabase v2: data changes for the Edge redesign, approved by Yousef 2026-10-21.
-- Part A (this file) is additive only, so My Fifty keeps working unchanged.
-- Part B (role/PRP renames, designation list, dropping the unique email) waits until My Fifty's code is patched.

-- contacts: new list values (renames and removals are in part B)
alter type contacts_role add value if not exists 'dentist';
alter type contacts_filler add value if not exists 'yvoire';
alter type contacts_filler add value if not exists 'none';
alter type contacts_prp add value if not exists 'alyssamed';
alter type contacts_prp add value if not exists 'cellenis';
alter type contacts_prp add value if not exists 'world_prp';
alter type contacts_prp add value if not exists 'naturagel';
alter type contacts_prp add value if not exists 'none';

-- contacts: the customer's medical director, pre-filled from onboarding, changeable by the rep
alter table contacts add column if not exists medical_director_id uuid references contacts(id);
create index if not exists contacts_medical_director_id_idx on contacts (medical_director_id);
comment on column contacts.medical_director_id is 'The medical director for this customer (their own contact). Filled from the latest onboarding''s MD; the rep can change it';
with latest as (
  select distinct on (x.cid) x.cid, x.md
  from (select primary_contact_id as cid, md_contact_id as md, submitted_at from onboardings
        union all select injector_contact_id, md_contact_id, submitted_at from onboardings) x
  where x.cid is not null and x.md is not null and x.cid <> x.md
  order by x.cid, x.submitted_at desc nulls last
)
update contacts c set medical_director_id = latest.md from latest
where c.id = latest.cid and c.medical_director_id is null;

-- forecasts: a Vienna or event tag (rewards Renellence gives the customer)
do $$ begin create type forecasts_tag as enum ('vienna', 'event'); exception when duplicate_object then null; end $$;
alter table forecasts add column if not exists tag forecasts_tag;
comment on column forecasts.tag is 'vienna or event: the reward the customer is working toward. Empty = none';

-- events: two more kinds
alter type events_kind add value if not exists 'dinner';
alter type events_kind add value if not exists 'clinic_event';

-- events: reps can see events and invite their own contacts; creating events stays admin-only
drop policy if exists rep_read on events;
create policy rep_read on events for select to authenticated using (deleted_at is null and me() is not null);
drop policy if exists rep_invite on event_attendees;
create policy rep_invite on event_attendees for insert to authenticated with check (can_see_contact(contact_id));
drop policy if exists rep_update on event_attendees;
create policy rep_update on event_attendees for update to authenticated using (can_see_contact(contact_id)) with check (can_see_contact(contact_id));

-- tasks: the 1-on-1 "Focus this week" points
alter type tasks_source add value if not exists 'one_on_one';

-- marketing_requests (0 rows): free-form requests, status follows the design, file emailed by hand
alter table marketing_requests
  drop column if exists pillar, drop column if exists design_id, drop column if exists branding,
  drop column if exists brief, drop column if exists final_file_id, drop column if exists ready_sent_at,
  drop column if exists fields,
  add column if not exists campaign text, add column if not exists goal text, add column if not exists details text,
  add column if not exists in_design_at timestamptz, add column if not exists ready_at timestamptz,
  add column if not exists delivered_at timestamptz;
alter table marketing_requests alter column status drop default;
alter type marketing_requests_status rename to marketing_requests_status_old;
create type marketing_requests_status as enum ('sent', 'in_design', 'ready', 'delivered', 'declined', 'cancelled');
alter table marketing_requests alter column status type marketing_requests_status using 'sent'::marketing_requests_status;
drop type marketing_requests_status_old;

-- expenses: receipts from the Telegram bot (n8n writes them); Edge tags the customer and type
do $$ begin create type expenses_type as enum ('lunch', 'snacks_beverages', 'dinner', 'parking'); exception when duplicate_object then null; end $$;
do $$ begin create type expenses_status as enum ('to_submit', 'submitted'); exception when duplicate_object then null; end $$;
create table if not exists expenses (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references users(id),
  vendor text,
  amount numeric,
  currency text default 'CAD',
  spent_on date,
  contact_id uuid references contacts(id),
  type expenses_type,
  description text,
  status expenses_status default 'to_submit',
  submitted_at timestamptz,
  source text,
  external_id text unique,
  deleted_at timestamptz,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);
comment on table expenses is 'Rep expense receipts. n8n writes them from the Telegram bot; Edge tags the customer, type and description';
