-- ==== db/v2-007-part-b.sql
-- Supabase v2: Edge redesign part B, approved by Yousef 2026-10-21. Applied once My Fifty was ready for it
-- (my-fifty ef4d8c8: it reads old and new names and writes whichever the database has).
begin;

-- Roles: physician · injector · dentist · manager · other (nurse_injector -> injector, clinic_owner -> manager)
update contacts set role = 'manager' where role = 'clinic_owner';
alter type contacts_role rename to contacts_role_old;
create type contacts_role as enum ('physician', 'injector', 'dentist', 'manager', 'other');
alter table contacts alter column role type contacts_role
  using (case role::text when 'nurse_injector' then 'injector' when 'clinic_owner' then 'manager' else role::text end)::contacts_role;
drop type contacts_role_old;

-- PRP/PRF: exprecell -> exprecell_prf, arthrex_angel -> arthrex_prf, emcyte removed (nobody has it)
alter table contacts alter column prp_used drop default;
alter type contacts_prp rename to contacts_prp_old;
create type contacts_prp as enum ('exprecell_prf', 'arthrex_prf', 'alyssamed', 'regenlab', 'eclipse_prp', 'cellenis', 'world_prp', 'naturagel', 'other', 'none');
-- (ALTER ... USING can't hold a subquery, so the mapping is a throwaway function)
create function pg_temp.prp_map(a text[]) returns contacts_prp[] language sql as $$
  select coalesce(array_agg(case v when 'exprecell' then 'exprecell_prf' when 'arthrex_angel' then 'arthrex_prf' else v end)
                  filter (where v <> 'emcyte'), '{}')::contacts_prp[]
    from unnest(a) as v $$;
alter table contacts alter column prp_used type contacts_prp[] using pg_temp.prp_map(prp_used::text[]);
alter table contacts alter column prp_used set default '{}';
drop type contacts_prp_old;

-- Designation: a fixed list (lower case); anything else becomes 'other'
create type contacts_designation as enum ('md', 'rn', 'rpn', 'np', 'dds', 'other');
alter table contacts alter column designation type contacts_designation
  using (case when designation is null or btrim(designation) = '' then null
              when lower(btrim(designation)) in ('md', 'rn', 'rpn', 'np', 'dds') then lower(btrim(designation))
              else 'other' end)::contacts_designation;

-- Email: shared emails allowed (the apps warn); a plain index keeps look-ups fast
alter table contacts drop constraint if exists contacts_email_key;
create index if not exists contacts_email_idx on contacts (email);

commit;

