-- Functions whose bodies named old columns or tables
create or replace function public.is_admin() returns boolean
  language sql stable security definer set search_path to 'public' as $function$
  select exists (select 1 from users where auth_user_id = (select auth.uid()) and kind = 'admin' and is_active is not false)
$function$;

create or replace function public.me() returns uuid
  language sql stable security definer set search_path to 'public' as $function$
  select id from users where auth_user_id = (select auth.uid()) and is_active is not false
$function$;

alter function public.change_log_append_only() rename to change_logs_append_only;
create or replace function public.change_logs_append_only() returns trigger
  language plpgsql as $function$
begin
  if tg_op = 'INSERT' then new.changed_at := now(); return new; end if;
  raise exception 'change_logs is append-only';
end $function$;

create or replace function public.log_settings() returns trigger
  language plpgsql security definer set search_path to 'public' as $function$
begin
  insert into change_logs (changed_at, actor_user_id, actor_kind, source, action, entity_type, field_name, old_value, new_value)
  values (now(), nullif(current_setting('app.user_id', true), '')::uuid,
          case when nullif(current_setting('app.user_id', true), '') is null then 'system' else 'user' end::change_logs_actor_kind,
          coalesce(nullif(current_setting('app.source', true), ''), 'db_trigger')::change_logs_source,
          lower(tg_op), 'settings', coalesce(new.key, old.key),
          case when tg_op <> 'INSERT' then old.value end, case when tg_op <> 'DELETE' then new.value end);
  return null;
end $function$;

create or replace function public.log_changes() returns trigger
  language plpgsql security definer set search_path to 'public' as $function$
declare
  actor uuid := nullif(current_setting('app.user_id', true), '')::uuid;
  src text := coalesce(nullif(current_setting('app.source', true), ''), 'db_trigger');
  batch uuid := coalesce(nullif(current_setting('app.batch_id', true), '')::uuid, gen_random_uuid());
  old_j jsonb := case when tg_op <> 'INSERT' then to_jsonb(old) else '{}'::jsonb end;
  new_j jsonb := case when tg_op <> 'DELETE' then to_jsonb(new) else '{}'::jsonb end;
  row_id uuid := coalesce((new_j->>'id')::uuid, (old_j->>'id')::uuid);
  cid uuid;
  k text;
  secret boolean;
begin
  if actor is null then
    select u.id into actor from users u where u.auth_user_id = (select auth.uid());
  end if;
  cid := case tg_table_name
           when 'contacts' then row_id
           when 'onboardings' then coalesce((new_j->>'primary_contact_id')::uuid, (old_j->>'primary_contact_id')::uuid)
           else coalesce((new_j->>'contact_id')::uuid, (old_j->>'contact_id')::uuid)
         end;
  if tg_table_name in ('order_lines', 'payments') then
    select o.contact_id into cid from orders o where o.id = coalesce((new_j->>'order_id')::uuid, (old_j->>'order_id')::uuid);
  end if;
  if tg_op = 'INSERT' then
    insert into change_logs (changed_at, actor_user_id, actor_kind, source, action, entity_type, entity_id, contact_id, batch_id)
    values (now(), actor, case when actor is null then 'integration' else 'user' end::change_logs_actor_kind, src::change_logs_source,
            'create', tg_table_name, row_id, cid, batch);
  elsif tg_op = 'DELETE' then
    insert into change_logs (changed_at, actor_user_id, actor_kind, source, action, entity_type, entity_id, contact_id, batch_id)
    values (now(), actor, case when actor is null then 'integration' else 'user' end::change_logs_actor_kind, src::change_logs_source,
            'delete', tg_table_name, row_id, cid, batch);
  else
    for k in select key from jsonb_each(new_j) loop
      continue when k in ('updated_at', 'created_at');
      continue when (old_j->k) is not distinct from (new_j->k);
      secret := (tg_table_name = 'connections' and k = 'credentials_encrypted');
      insert into change_logs (changed_at, actor_user_id, actor_kind, source, action, entity_type, entity_id, contact_id, field_name, old_value, new_value, batch_id, is_sensitive)
      values (now(), actor, case when actor is null then 'integration' else 'user' end::change_logs_actor_kind, src::change_logs_source,
              case when k = 'owner_id' then 'reassign' when k = 'deleted_at' and (new_j->>k) is not null then 'delete' else 'update' end,
              tg_table_name, row_id, cid, k,
              case when secret then '"***"'::jsonb else old_j->k end,
              case when secret then '"***"'::jsonb else new_j->k end,
              batch, secret);
    end loop;
  end if;
  return null;
end $function$;

commit;

-- ==== db/v2-009-forecast-activities.sql
-- Supabase v2: Forecast activities (Training · Vienna · Event), approved by Yousef 2026-10-23
-- (docs/forecast-activities-proposal.md, option A, with an exact day).
-- A rep adds an activity for a customer on the Forecast page, on its own, with no amount and no target. It replaces the
-- forecast's "Customer reward" (forecasts.customer_benefit), which Edge no longer writes; the column stays for now
-- (dropping it and its enum is a later step).
-- One transaction. Additive only: My Fifty reads neither table, so it keeps working unchanged.

create type forecast_activities_activity_kind as enum ('training', 'vienna', 'event');

create table forecast_activities (
  id uuid primary key default gen_random_uuid(),
  -- on delete cascade: an activity belongs to its customer, so the demo/test wipes (which hard-delete fake contacts)
  -- never stop on it. Real contacts are only ever soft-deleted.
  contact_id uuid not null references contacts(id) on delete cascade,
  rep_id uuid references users(id),
  activity_kind forecast_activities_activity_kind not null,
  due_date date not null,
  created_by_id uuid references users(id),
  deleted_at timestamptz,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);
create index forecast_activities_contact_id_idx on forecast_activities (contact_id);

comment on table forecast_activities is 'A planned activity for a customer, shown on the Forecast page: training, Vienna or event, on an exact day. Never counted as money, Late or Ordered';
comment on column forecast_activities.rep_id is 'The credited rep: the customer''s owner when it was added (as forecasts)';
comment on column forecast_activities.activity_kind is 'training · vienna · event';
comment on column forecast_activities.due_date is 'The day the rep picked; not in the past when added';

-- Access as forecasts: a rep reaches the rows of their own customers, admins all (can_see_contact).
alter table forecast_activities enable row level security;
create policy by_contact on forecast_activities for all to authenticated
  using (public.can_see_contact(contact_id)) with check (public.can_see_contact(contact_id));
grant select, insert, update, delete, truncate, references, trigger on forecast_activities to anon, authenticated, service_role;

-- Carry the live forecast rewards over as activities on the forecast's due day (the forecasts keep their value).
insert into forecast_activities (contact_id, rep_id, activity_kind, due_date, created_by_id, created_at, updated_at)
select f.contact_id, f.rep_id, f.customer_benefit::text::forecast_activities_activity_kind, f.due_date, f.created_by_id, f.created_at, f.updated_at
  from forecasts f
 where f.customer_benefit is not null and f.deleted_at is null and f.contact_id is not null and f.due_date is not null;

-- Triggers as on forecasts, made after the copy so the carried-over rows add no change_logs rows.
create trigger touch_updated_at before update on forecast_activities for each row execute function touch_updated_at();
create trigger log_changes after insert or update or delete on forecast_activities for each row execute function log_changes();

-- ==== db/v2-010-compass.sql
-- Supabase v2: Compass, the weekly sales loop (Friday check-in -> weekly 1-on-1 -> the week in Pulse; monthly 1-on-1).
-- APPROVED by Yousef 2026-10-23 (compass/docs/compass-data-proposal.md, from compass/db/compass-001-proposal.sql):
--   the 5 tables checkins, account_picks, forecast_changes, one_on_ones, fifty_statuses; tasks.one_on_one_id;
--   change_logs_source + 'compass'; the settings row 'compass'.
--   Design choices (all the recommended options): parked-until is derived, not stored; forecasts from the monthly
--   1-on-1 are normal forecasts; weekly and monthly sessions share one_on_ones (kind); Done and Missed are columns on
--   account_picks (visit_interaction_id, missed_at; no missed reason).
-- NOT in this file (deferred by the owner): events.customer_reward, and dropping forecast_activities.
--
-- One transaction. Additive only: no existing row changes, apart from the one new settings row (and its change_logs
-- 'create' row from the settings trigger). Applied with the scratchpad's compass-apply/apply.js (v1 first, then v2),
-- which runs this body inside its own transaction and checks the counts.
-- Postgres 17 (v1 and v2 are 17.11) allows ALTER TYPE ... ADD VALUE inside a transaction; the new value just can't be
-- used before commit. Nothing below uses 'compass' (the settings insert logs with source db_trigger), so it is safe here.
begin;

-- ---------- 1. Fixed lists (enums), named <table>_<column> ---------------------------------------------------
create type account_picks_pick as enum ('visit', 'call', 'wait', 'park');                 -- suggested_pick, rep_pick, final_pick
create type account_picks_sort_group as enum ('candidate', 'onboarded', 'fifty', 'lead'); -- frozen at the check-in
create type account_picks_second_look_decision as enum ('keep', 'change');
create type forecast_changes_change_kind as enum ('moved', 'dropped', 'pushed_later', 'reduced', 'went_up', 'pulled_forward');
create type forecast_changes_reason as enum (
  'clinic_timing', 'still_has_stock', 'budget', 'decision_maker_unreachable', 'no_next_step', 'chose_other_brand',
  'estimate_off', 'more_patient_demand', 'new_product_line', 'clinic_pulled_forward');
create type one_on_ones_kind as enum ('weekly', 'monthly');
create type one_on_ones_skill as enum ('price_pushback', 'ask_for_order', 'book_next_step', 'gatekeeper', 'cold_visit', 'plan_week');
create type one_on_ones_roleplay_character as enum ('skeptic', 'fence_sitter', 'rusher', 'fan', 'gatekeeper', 'newcomer');
create type fifty_statuses_status as enum ('on_track', 'watch', 'at_risk');

-- New value in an existing list: changes made from Compass are told apart in change_logs (like my_fifty).
alter type change_logs_source add value if not exists 'compass';

-- ---------- 2. checkins: the rep's Friday check-in, one per rep per week -------------------------------------
create table checkins (
  id uuid primary key default gen_random_uuid(),
  rep_id uuid not null references users(id),
  week_start_date date not null,
  submitted_at timestamptz,
  help_note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (rep_id, week_start_date),
  constraint checkins_week_start_is_monday check (extract(isodow from week_start_date) = 1)
);
comment on table checkins is 'The rep''s Friday check-in: one per rep per week';
comment on column checkins.week_start_date is 'The Monday of the week being planned';
comment on column checkins.submitted_at is 'Empty = still a draft';
comment on column checkins.help_note is '"Where I need help from <manager>" (optional); shown first in the 1-on-1';

-- ---------- 3. account_picks: every account the rep sorted on Friday, and how its week ended --------------------
create table account_picks (
  id uuid primary key default gen_random_uuid(),
  checkin_id uuid not null references checkins(id) on delete cascade,
  contact_id uuid not null references contacts(id),
  sort_group account_picks_sort_group not null,
  suggested_pick account_picks_pick not null,
  suggested_reason text not null,
  rep_pick account_picks_pick not null,
  final_pick account_picks_pick,
  purpose text,
  second_look_fact text,
  second_look_decision account_picks_second_look_decision,
  visit_interaction_id uuid references interactions(id),
  missed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (checkin_id, contact_id),
  constraint account_picks_done_or_missed check (visit_interaction_id is null or missed_at is null)
);
comment on table account_picks is 'Every account the rep sorted on Friday, and how its week ended. Parked-until is derived (latest final_pick park + settings.compass.park_days), never stored';
comment on column account_picks.sort_group is 'Frozen: the group the account was in on Friday (SOP rule 9)';
comment on column account_picks.suggested_reason is 'The one-line reason shown next to "Suggested" (frozen)';
comment on column account_picks.rep_pick is 'What the rep chose on Friday (kept as it was)';
comment on column account_picks.final_pick is 'What was agreed on Monday; empty until the 1-on-1 is saved';
comment on column account_picks.purpose is 'The visit or call purpose, written from the meeting notes';
comment on column account_picks.second_look_fact is 'Set when the pick is queued for Second look (a plain fact line)';
comment on column account_picks.visit_interaction_id is 'Done: the Pulse visit that closed it';
comment on column account_picks.missed_at is 'Missed: when the rep marked it missed in Pulse (no reason asked, owner 2026-10-23)';

-- ---------- 4. forecast_changes: the reason for each forecast change made on Friday ---------------------------
-- The old and new values themselves stay in change_logs (forecasts already has the log_changes trigger).
create table forecast_changes (
  id uuid primary key default gen_random_uuid(),
  forecast_id uuid not null references forecasts(id),
  checkin_id uuid not null references checkins(id) on delete cascade,
  change_kind forecast_changes_change_kind not null,
  reason forecast_changes_reason not null,
  created_by_id uuid references users(id),
  created_at timestamptz not null default now(),
  unique (checkin_id, forecast_id)
);
comment on table forecast_changes is 'Why a forecast changed at the Friday check-in. Append-style (no updated_at); old and new values are in change_logs';

-- ---------- 5. one_on_ones: each weekly or monthly 1-on-1 ---------------------------------------------------
create table one_on_ones (
  id uuid primary key default gen_random_uuid(),
  kind one_on_ones_kind not null,
  rep_id uuid not null references users(id),
  held_by_id uuid references users(id),
  session_date date not null,
  checkin_id uuid references checkins(id),
  focus_action_target_count integer check (focus_action_target_count between 1 and 15),
  skill one_on_ones_skill,
  roleplay_character one_on_ones_roleplay_character,
  roleplay_done_at timestamptz,
  completed_at timestamptz,
  week_confirmed_at timestamptz,
  deleted_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (rep_id, kind, session_date),
  constraint one_on_ones_weekly_fields check (kind = 'weekly' or (checkin_id is null and focus_action_target_count is null and roleplay_character is null and roleplay_done_at is null and week_confirmed_at is null))
);
comment on table one_on_ones is 'Each weekly or monthly 1-on-1 (kind). Forecasts added in the monthly session are normal forecasts (change_logs source compass)';
comment on column one_on_ones.held_by_id is 'The admin who ran it';
comment on column one_on_ones.checkin_id is 'Weekly: the Friday check-in it starts from';
comment on column one_on_ones.focus_action_target_count is 'Weekly: the lead measure, 1-15';
comment on column one_on_ones.skill is 'Weekly: the roleplay skill; monthly: the skill of the month';
comment on column one_on_ones.completed_at is '"Save the week" / "Save <month>"';
comment on column one_on_ones.week_confirmed_at is 'Weekly: the rep''s one tap in Pulse';

-- The weekly focus stays Edge's task (source one_on_one, title = goal key); the manager's commitments are tasks too
-- (assignee = the manager, no contact). Both are tied to their session by this one new column.
alter table tasks add column one_on_one_id uuid references one_on_ones(id);
comment on column tasks.one_on_one_id is 'The 1-on-1 that set it: the weekly focus task, or a manager commitment';

-- ---------- 6. fifty_statuses: once a month, every My Fifty account gets a status --------------------------
create table fifty_statuses (
  id uuid primary key default gen_random_uuid(),
  contact_id uuid not null references contacts(id),
  month_start_date date not null check (extract(day from month_start_date) = 1),
  status fifty_statuses_status not null,
  one_on_one_id uuid references one_on_ones(id),
  set_by_id uuid references users(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (contact_id, month_start_date)
);
comment on table fifty_statuses is 'A status for every My Fifty account, once a month, set in the monthly 1-on-1';
comment on column fifty_statuses.month_start_date is 'The 1st of the month';

-- ---------- 7. Indexes on every column a rule or a screen filters on (SOP section 7) ------------------------
-- (checkin_id on account_picks and forecast_changes is covered by their unique keys, which start with it.)
create index checkins_rep_id_idx on checkins (rep_id);
create index account_picks_contact_id_idx on account_picks (contact_id);
create index account_picks_final_pick_idx on account_picks (final_pick) where final_pick = 'park';
create index account_picks_visit_interaction_id_idx on account_picks (visit_interaction_id);
create index forecast_changes_forecast_id_idx on forecast_changes (forecast_id);
create index one_on_ones_rep_id_idx on one_on_ones (rep_id, session_date desc);
create index one_on_ones_checkin_id_idx on one_on_ones (checkin_id);
create index tasks_one_on_one_id_idx on tasks (one_on_one_id);
create index fifty_statuses_month_idx on fifty_statuses (month_start_date);
create index fifty_statuses_one_on_one_id_idx on fifty_statuses (one_on_one_id);

-- ---------- 8. Standard triggers: updated_at and the change log ------------------------------------------
-- Every insert, update and delete is logged, account_picks inserts included (owner 2026-10-23).
do $$
declare t text;
begin
  foreach t in array array['checkins', 'account_picks', 'one_on_ones', 'fifty_statuses'] loop
    execute format('create trigger touch_updated_at before update on public.%I for each row execute function public.touch_updated_at()', t);
  end loop;
  foreach t in array array['checkins', 'account_picks', 'forecast_changes', 'one_on_ones', 'fifty_statuses'] loop
    execute format('create trigger log_changes after insert or update or delete on public.%I for each row execute function public.log_changes()', t);
  end loop;
end $$;

-- ---------- 9. Row-level security (SOP section 7): a rep sees only their own; admins see all ----------------
create or replace function public.can_see_checkin(cid uuid) returns boolean
  language sql stable security definer set search_path = public as $$
  select public.is_admin() or exists (select 1 from checkins c where c.id = cid and c.rep_id = public.me())
$$;

alter table checkins enable row level security;
create policy own on checkins for all to authenticated
  using (rep_id = me() or is_admin()) with check (rep_id = me() or is_admin());

alter table account_picks enable row level security;
create policy by_checkin on account_picks for all to authenticated
  using (can_see_checkin(checkin_id)) with check (can_see_checkin(checkin_id) and can_see_contact(contact_id));

alter table forecast_changes enable row level security;
create policy by_checkin on forecast_changes for all to authenticated
  using (can_see_checkin(checkin_id)) with check (can_see_checkin(checkin_id) and can_see_contact((select f.contact_id from forecasts f where f.id = forecast_id)));

-- 1-on-1s: the rep reads their own; only admins create or change them (the rep's week confirmation goes through
-- Pulse's server, which checks the rep).
alter table one_on_ones enable row level security;
create policy rep_read on one_on_ones for select to authenticated using (deleted_at is null and (rep_id = me() or is_admin()));
create policy admin_write on one_on_ones for all to authenticated using (is_admin()) with check (is_admin());

-- My Fifty statuses: readable with the contact; set by admins in the monthly 1-on-1.
alter table fifty_statuses enable row level security;
create policy by_contact_read on fifty_statuses for select to authenticated using (can_see_contact(contact_id));
create policy admin_write on fifty_statuses for all to authenticated using (is_admin()) with check (is_admin());

-- Table grants as every v2 table (v2-009); RLS above decides the rows.
grant select, insert, update, delete, truncate, references, trigger on checkins, account_picks, forecast_changes, one_on_ones, fifty_statuses
  to anon, authenticated, service_role;

-- ---------- 10. Settings row (data, not structure): the loop's thresholds, never hard-coded ------------------
insert into settings (key, value) values ('compass', jsonb_build_object(
  'max_visits', 15, 'park_days', 30, 'second_look_max', 4,
  'sampled_no_order_days', 20, 'fifty_quiet_days', 30, 'checkin_due_weekday', 5, 'checkin_due_time', '17:00'))
on conflict (key) do nothing;

commit;

-- ==== db/v2-013-attendees.sql
-- v2-013: one attendees table for events AND expenses. APPROVED by Yousef 2026-10-27 ("go ahead with option 1").
-- Apply with: node renellence-ops/ops/attendees/apply-v2-013.js v1|v2 [--dry]   (one transaction, checks, rollback on surprise)
--
-- Why: Edge's Expenses page records who was at a meal (Lunch, Dinner, Snacks/Beverages; never Parking), so spend per
-- person and per customer can be worked out later. The owner chose to combine those people with event attendees in
-- one table, `attendees` (SOP rule 8: one nullable link per possible parent plus an "exactly one is filled" rule, as
-- in files), over a separate expense_attendees table.
--
-- What changes:
--   1. event_attendees is renamed attendees; its list type event_attendees_status -> attendees_status, and its
--      constraints and indexes follow the new name. Every existing row (all event rows) stays as it is.
--   2. New columns: expense_id (-> expenses), first_name, last_name, role (the contacts_role list: physician, injector
--      (shown as "Nurse"), dentist, manager, other). Name and role are for people typed in by hand; a linked customer
--      (contact_id) is shown from their own record.
--   3. Rules: exactly one of event_id / expense_id; a row is either a linked customer or has a typed first name;
--      one row per customer per expense (as per event).
--   4. Access: event rows keep their rules (whoever can see the contact). Expense rows follow their expense: the rep
--      who owns it, or an admin (as the expenses table).
-- Not stored (derived when read, SOP rule 4): cost per person, spend per customer.
-- Code that reads the old name (Edge api/_edge reads.js + writes.js, Compass api/_compass reads.js + rules.js) is
-- switched in the same push as this is applied.
begin;

-- 1. The rename
alter table event_attendees rename to attendees;
alter type event_attendees_status rename to attendees_status;
alter table attendees rename constraint event_attendees_pkey to attendees_pkey;
alter table attendees rename constraint event_attendees_event_id_fkey to attendees_event_id_fkey;
alter table attendees rename constraint event_attendees_contact_id_fkey to attendees_contact_id_fkey;
alter table attendees rename constraint event_attendees_invited_by_id_fkey to attendees_invited_by_id_fkey;
alter table attendees rename constraint event_attendees_event_id_contact_id_key to attendees_event_id_contact_id_key;
alter index event_attendees_contact_idx rename to attendees_contact_id_idx;

-- 2. Expense attendees
alter table attendees add column expense_id uuid references expenses(id);
alter table attendees add column first_name text;
alter table attendees add column last_name text;
alter table attendees add column role contacts_role;
create index attendees_expense_id_idx on attendees (expense_id);

-- 3. Rules
alter table attendees add constraint attendees_one_parent check (num_nonnulls(event_id, expense_id) = 1);
alter table attendees add constraint attendees_person check (contact_id is not null or nullif(btrim(first_name), '') is not null);
alter table attendees add constraint attendees_expense_id_contact_id_key unique (expense_id, contact_id);

comment on table attendees is 'Who was at an event or an expense (a meal). One row per event or expense + person: a linked customer (contact_id) or a name typed in (first_name, last_name, role)';
comment on column attendees.expense_id is 'The expense (a meal) this person was at; exactly one of event_id / expense_id is filled';
comment on column attendees.first_name is 'Only for someone typed in by hand (no contact_id)';
comment on column attendees.last_name is 'Only for someone typed in by hand (no contact_id)';
comment on column attendees.role is 'Only for someone typed in by hand; a linked customer''s role comes from their contact';

-- 4. Access: the old rules now cover event rows only; expense rows follow their expense
drop policy by_contact on attendees;
drop policy rep_invite on attendees;
drop policy rep_update on attendees;
create policy by_contact on attendees for select to authenticated using (event_id is not null and can_see_contact(contact_id));
create policy rep_invite on attendees for insert to authenticated with check (event_id is not null and can_see_contact(contact_id));
create policy rep_update on attendees for update to authenticated using (event_id is not null and can_see_contact(contact_id)) with check (event_id is not null and can_see_contact(contact_id));
create policy by_expense on attendees for all to authenticated
  using (expense_id is not null and exists (select 1 from expenses x where x.id = expense_id and (x.user_id = me() or is_admin())))
  with check (expense_id is not null and exists (select 1 from expenses x where x.id = expense_id and (x.user_id = me() or is_admin())));

commit;

-- ==== db/v2-014-quo-unmatched.sql
-- v2-014: Quo calls and texts from numbers that are not in the book yet (approved by Yousef 2026-10-27).
--
-- Owner's rule (2026-10-23, option 2): Quo never creates a contact or lead. A call or text with a number nobody in v2
-- has is kept here quietly, keyed by the phone number, and never shown to reps. When a contact is created with that
-- number (Pulse, Edge, n8n's intake, an import: any path) or a contact gets that number later, the trigger below turns
-- the held rows into that contact's interactions (and Quo's AI call summary into ai_outputs), exactly as Pulse's Quo
-- webhook (my-fifty api/quo.js) would have written them. Matched calls and texts never come here.
begin;

create table public.quo_unmatched (
  id uuid primary key default gen_random_uuid(),
  phone text not null,
  kind public.interactions_kind not null,
  direction public.interactions_direction,
  quo_id text not null,
  line_id text,
  occurred_at timestamptz not null,
  payload jsonb not null,
  attached_contact_id uuid references public.contacts(id) on delete set null,
  attached_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint quo_unmatched_quo_id_key unique (quo_id),
  constraint quo_unmatched_kind_check check (kind in ('call', 'text'))
);
comment on table public.quo_unmatched is 'Quo calls and texts from numbers no contact has yet (owner 2026-10-23: Quo never creates contacts). Attached to a contact automatically when one gets that number (attach_quo_unmatched trigger). Never shown to reps.';
comment on column public.quo_unmatched.phone is 'The outside number, E.164 (+1...)';
comment on column public.quo_unmatched.quo_id is 'Quo''s call (AC...) or message id; the interaction''s external_id';
comment on column public.quo_unmatched.line_id is 'The Renellence Quo line (phone number id, PN...)';
comment on column public.quo_unmatched.payload is 'The interactions columns the call or text becomes (built by Pulse api/quo.js); optional _summary = Quo''s AI call summary';
comment on column public.quo_unmatched.attached_contact_id is 'The contact it was attached to (null = still waiting)';

create index quo_unmatched_waiting_idx on public.quo_unmatched (right(regexp_replace(phone, '\D', '', 'g'), 10)) where attached_at is null;

alter table public.quo_unmatched enable row level security;
create policy admin_read on public.quo_unmatched for select to authenticated using (is_admin());

create trigger touch_updated_at before update on public.quo_unmatched for each row execute function public.touch_updated_at();
create trigger log_changes after insert or update or delete on public.quo_unmatched for each row execute function public.log_changes();

-- The migration's fixed ids (renellence-ops/ops/migration/build.js uid): md5 of the namespace + key, shaped as a v4 uuid,
-- so a call attached here gets the same id the load or Pulse would give it.
create or replace function public.migration_uid(k text) returns uuid language sql immutable as $$
  select (substr(h, 1, 8) || '-' || substr(h, 9, 4) || '-4' || substr(h, 14, 3) || '-'
          || to_hex(((('x' || substr(h, 17, 1))::bit(4)::int) & 3) | 8) || substr(h, 18, 3) || '-' || substr(h, 21, 12))::uuid
    from (select md5('renellence-migration-2026-10-22:' || k) h) x
$$;

create or replace function public.attach_quo_unmatched() returns trigger language plpgsql security definer set search_path = public as $$
declare
  nums text[];
  q record;
  iid uuid;
begin
  if new.deleted_at is not null or new.merged_into_contact_id is not null then return new; end if;
  nums := array(select d from unnest(array[right(regexp_replace(coalesce(new.phone, ''), '\D', '', 'g'), 10),
                                            right(regexp_replace(coalesce(new.mobile_phone, ''), '\D', '', 'g'), 10)]) d where length(d) = 10);
  if coalesce(array_length(nums, 1), 0) = 0 then return new; end if;
  for q in select * from quo_unmatched where attached_at is null and right(regexp_replace(phone, '\D', '', 'g'), 10) = any(nums) order by occurred_at loop
    iid := migration_uid('int:quo|' || q.quo_id || '|' || new.id::text);
    insert into interactions select * from jsonb_populate_record(null::interactions,
      (q.payload - '_summary') || jsonb_build_object('id', iid, 'contact_id', new.id, 'created_at', q.occurred_at, 'updated_at', now()))
    on conflict do nothing;
    if q.payload ? '_summary' and exists (select 1 from interactions where id = iid) then
      insert into ai_outputs (id, kind, interaction_id, output_text, model_name, created_at)
      values (migration_uid('ai:' || iid::text), 'call_summary', iid, q.payload->>'_summary', 'quo', q.occurred_at)
      on conflict do nothing;
    end if;
    update quo_unmatched set attached_contact_id = new.id, attached_at = now() where id = q.id;
  end loop;
  return new;
end $$;
comment on function public.attach_quo_unmatched() is 'Turns held Quo calls/texts (quo_unmatched) into interactions when a contact gets their number (v2-014)';

create trigger attach_quo_unmatched after insert or update of phone, mobile_phone on public.contacts
  for each row execute function public.attach_quo_unmatched();

commit;

-- ==== db/v2-015-streak-nudge.sql
-- v2-015 (approved by Yousef 2026-10-28): the 3 pm streak nudge push (Pulse, Final Mockup (3) N4).
-- One new notification kind; nothing else changes. Safe to re-run.
begin;
alter type notifications_kind add value if not exists 'streak_nudge';
commit;

-- ==== db/v2-016-ai-runs.sql
-- v2-016 (approved by Yousef 2026-10-28): Claude job run log and result kinds.
-- Every Claude API job (renellence-ops/ops/claude runner) writes one ai_runs row per run; the month's spend is summed
-- from it to enforce the cost cap. Job results still go to ai_outputs, with the new kinds below (the runner's store has
-- been the local ledger file until now: ops/claude/ledger.js). Safe to re-run.
begin;

alter type ai_outputs_kind add value if not exists 'data_health';
alter type ai_outputs_kind add value if not exists 'enrichment';
alter type ai_outputs_kind add value if not exists 'gap_ranking';
alter type ai_outputs_kind add value if not exists 'monday_prep';
alter type ai_outputs_kind add value if not exists 'focus_actions';
alter type ai_outputs_kind add value if not exists 'meeting_notes';

create table if not exists public.ai_runs (
  id uuid primary key default gen_random_uuid(),
  job text not null,
  at timestamptz not null default now(),
  prompt_version text,
  prompt_hash text,
  models_planned text[],
  model_used text,
  result text,
  attempts jsonb not null default '[]'::jsonb,
  fallbacks jsonb not null default '[]'::jsonb,
  tokens jsonb not null default '{}'::jsonb,
  cost_usd numeric(12,6) not null default 0,
  validation text,
  blocked text,
  stopped text,
  cap_usd numeric(10,2),
  month_spend_before_usd numeric(12,6),
  month_spend_after_usd numeric(12,6),
  cap_reached boolean,
  output jsonb,
  ms integer,
  created_at timestamptz not null default now(),
  constraint ai_runs_result_check check (result is null or result in ('claude', 'rules', 'none')),
  constraint ai_runs_validation_check check (validation is null or validation in ('passed', 'failed', 'not_reached'))
);
comment on table public.ai_runs is 'One row per Claude API job run: the spend, the model chain and the validation result. The cost cap sums the month from it. Written by the server only.';
comment on column public.ai_runs.job is 'The job id the runner was called with (picks · focus_actions · monday_prep · data_health · enrichment · gap_ranking · ...)';
comment on column public.ai_runs.result is 'How the run ended: claude (checked output) · rules (the fixed rules) · none (nothing)';
comment on column public.ai_runs.cost_usd is 'The run''s cost in USD (ops/claude/pricing.js prices it); the month''s spend and the cap read this column';
comment on column public.ai_runs.output is 'The checked JSON the run produced. May hold customer names: admins only.';

create index if not exists ai_runs_at_idx on public.ai_runs (at);
create index if not exists ai_runs_job_at_idx on public.ai_runs (job, at);

alter table public.ai_runs enable row level security;
drop policy if exists admin_read on public.ai_runs;
create policy admin_read on public.ai_runs for select to authenticated using (is_admin());
-- An append-only log: no updated_at column and no touch_updated_at / log_changes triggers.

commit;

-- ==== db/v2-017-rep-stage.sql
-- v2-017 (approved by Yousef 2026-10-29: "give them ability to make a contact a candidate or a lead"; answer: the rep's
-- choice sticks, orders still move it up): the stage a rep set by hand. Empty = worked out as before (samples ->
-- candidate, an order in the last 3 months -> My Fifty, else lead). A recent order still makes them My Fifty whatever
-- this says; the stage itself is still never stored. Safe to re-run.
begin;

do $$ begin
  create type public.contacts_rep_stage as enum ('lead', 'candidate');
exception when duplicate_object then null; end $$;

alter table public.contacts add column if not exists rep_stage public.contacts_rep_stage;
comment on column public.contacts.rep_stage is 'The stage the rep chose by hand (lead or candidate); empty = worked out from orders. A recent order makes them My Fifty whatever this says.';

commit;

-- ==== db/v2-018-event-reward.sql
-- v2-018 (approved by Yousef 2026-10-30, "approve the field"; the Oct 23 plan docs/event-rewards-plan.md, section 1 only):
-- the customer reward an event is. Customers whose RSVP is yes (attendees.status rsvp) or who attended get its label on the
-- Forecast page in the event's month; never counted as money. Admins set it. forecast_activities is NOT dropped here.
-- Safe to re-run.
begin;

do $$ begin
  create type public.events_customer_reward as enum ('vienna', 'training');
exception when duplicate_object then null; end $$;

alter table public.events add column if not exists customer_reward public.events_customer_reward;
comment on column public.events.customer_reward is 'vienna · training: the customer reward this event is. Customers with RSVP yes or attended get the label on the Forecast page in the event''s month. Empty = not a reward';

commit;

-- ==== db/v2-019-forecast-reason-other.sql
-- v2-019 (approved by Yousef 2026-11-02: "Yes, make it"): an "Other" reason for a forecast change in the Friday check-in,
-- with the rep's own words. Adds the value 'other' to forecast_changes_reason and the column forecast_changes.reason_note
-- (up to 300 characters; filled only when the reason is other). Safe to re-run.
alter type public.forecast_changes_reason add value if not exists 'other';

alter table public.forecast_changes add column if not exists reason_note text;
do $$ begin
  alter table public.forecast_changes add constraint forecast_changes_reason_note_len check (reason_note is null or char_length(reason_note) <= 300);
exception when duplicate_object then null; end $$;
comment on column public.forecast_changes.reason_note is 'What the rep typed when the reason is other (Friday check-in). Empty for every other reason';

-- ==== db/v2-020-expense-approved.sql
-- v2-020 (owner 2026-11-03, "Admin and Developer Views"): an admin approves a rep's submitted expenses for a month.
--   expenses_status gains 'approved' (to_submit -> submitted -> approved). Reps' screens show approved as submitted, so
--   nothing changes for them; Edge's Expenses (admin) approves and can undo (back to submitted). change_logs records who.
--   tech@renellence.com joins as an admin: with info@ and admin@ the developers (api/_edge/roles.js, a fixed list).
-- Safe to re-run.
alter type public.expenses_status add value if not exists 'approved';

insert into public.users (email, full_name, kind, is_active)
select 'tech@renellence.com', 'Tech Renellence', 'admin', true
 where not exists (select 1 from public.users where lower(email) = 'tech@renellence.com');

-- ==== db/v2-021-product-availability.sql
-- v2-021: product availability (owner 2026-11-03: "add a field to the products table that has yes or no for 'product
-- availability', if no then the product cant be selected"). A product stays listed on every order screen (Edge, Pulse) but
-- cannot be picked or ordered while is_available is false; is_active still means the product exists at all.
-- The saypha fact sheet (SAYPHA-PAMPHLET) is the first one marked unavailable. Safe to re-run.
begin;
alter table public.products add column if not exists is_available boolean not null default true;
comment on column public.products.is_available is 'Product availability: false = shown as unavailable on every order screen and refused on every order (owner 2026-11-03)';
update public.products set is_available = false, updated_at = now() where sku = 'SAYPHA-PAMPHLET' and is_available;
commit;
select sku, name, is_active, is_available from public.products where sku = 'SAYPHA-PAMPHLET';

